import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Type, type Static } from 'typebox';
import { errorMessage, parse } from '@atd/agent-contracts';

/**
 * The apple-design web kit generative views are styled with, and the view runtime that defines
 * `window.atd`. Both live in the package's `view-kit/` directory (package.json `files`):
 * `apple-kit.json` is generated by `scripts/vendor-view-kit.py` from `.agents/skills/apple-design`
 * and never edited by hand; `runtime.js` is written by hand. They are read once, on first use.
 */

/** Blocks every view's document carries, whatever its `show_ui` call names. */
export const ALWAYS_BLOCKS: readonly string[] = ['base', 'type', 'type-macos', 'states'];

/** Blocks a view gets beside `ALWAYS_BLOCKS` when its `show_ui` call names none. */
export const DEFAULT_BLOCKS: readonly string[] = ['button', 'card', 'list', 'motion'];

const KitBlockSchema = Type.Object(
  {
    /** Blocks this one needs before it, `tokens` excluded (build_kit.py `Block.deps()`). */
    requires: Type.Array(Type.String()),
    layer: Type.Union([Type.Literal('base'), Type.Literal('components')]),
    /** The block's minified CSS. */
    css: Type.String(),
    /** The block's minified classic script; empty when the block has none. */
    js: Type.String(),
  },
  { additionalProperties: false },
);
export type KitBlock = Static<typeof KitBlockSchema>;

/** `view-kit/apple-kit.json` as the vendoring script writes it. */
const KitFileSchema = Type.Object(
  {
    version: Type.Literal(1),
    source: Type.Object(
      { skill: Type.String(), inputsSha256: Type.String() },
      { additionalProperties: false },
    ),
    /** The cascade layer statement, `@layer apple.base, apple.components;`. */
    layers: Type.String(),
    /** The minified tokens.css, emitted unlayered. */
    tokens: Type.String(),
    /** apple-interactions.js as one minified classic script (build_kit.py `build_js`). */
    coreJs: Type.String(),
    blocks: Type.Record(Type.String(), KitBlockSchema),
  },
  { additionalProperties: false },
);

/** The kit and runtime as a view's document is assembled from them (document.ts). */
export interface ViewKit {
  layers: string;
  tokens: string;
  coreJs: string;
  /** Every block of the kit by name: the names `show_ui` may list. */
  blocks: ReadonlyMap<string, KitBlock>;
  /** `view-kit/runtime.js` as written. */
  runtime: string;
}

/** A block in a document's order. */
export interface OrderedBlock {
  name: string;
  block: KitBlock;
}

/**
 * The package's `view-kit` directory. Both `src/views/*.ts` and `dist/views/*.js` resolve to
 * `../../view-kit`, as product-skills resolve (builtins/manifest.ts).
 */
export function viewKitDir(): string {
  return path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'view-kit');
}

let loading: Promise<ViewKit> | null = null;

/**
 * The view kit, read and checked on first use and kept for the life of the process. A read that
 * failed is not kept, so the next call reads again.
 */
export function loadViewKit(): Promise<ViewKit> {
  loading ??= readViewKit(viewKitDir()).catch((error: unknown) => {
    loading = null;
    throw error;
  });
  return loading;
}

async function readViewKit(dir: string): Promise<ViewKit> {
  const [json, runtime] = await Promise.all([
    readFile(path.join(dir, 'apple-kit.json'), 'utf8'),
    readFile(path.join(dir, 'runtime.js'), 'utf8'),
  ]);
  return parseViewKit(json, runtime);
}

/**
 * Checks a kit file and builds the kit from it and the runtime. Beyond its shape, every document
 * must be able to order its blocks: each requirement names a block of the kit, no requirements
 * form a cycle, and the fixed blocks exist. Failures throw a plain Error, so a route answers with
 * a server fault rather than a bad request.
 */
export function parseViewKit(json: string, runtime: string): ViewKit {
  let file: Static<typeof KitFileSchema>;
  try {
    file = parse(KitFileSchema, JSON.parse(json));
  } catch (error) {
    throw new Error(`The view kit is invalid: ${errorMessage(error)}`, { cause: error });
  }
  const blocks = new Map(Object.entries(file.blocks));
  resolveBlocks([...ALWAYS_BLOCKS, ...DEFAULT_BLOCKS, ...blocks.keys()], blocks);
  return { layers: file.layers, tokens: file.tokens, coreJs: file.coreJs, blocks, runtime };
}

/**
 * The blocks a document emits, in build_kit.py `resolve` order: each block after the blocks it
 * requires, then base-layer blocks before component blocks with their relative order kept.
 * Throws on a name the kit does not have and on a dependency cycle.
 */
export function resolveBlocks(
  names: Iterable<string>,
  blocks: ReadonlyMap<string, KitBlock>,
): OrderedBlock[] {
  const order: OrderedBlock[] = [];
  const state = new Map<string, 'active' | 'done'>();
  const visit = (name: string, chain: readonly string[]): void => {
    const block = blocks.get(name);
    if (!block) {
      const via = chain.length ? ` (required by ${chain.at(-1)})` : '';
      throw new Error(`The view kit has no block ${name}${via}.`);
    }
    const seen = state.get(name);
    if (seen === 'done') return;
    if (seen === 'active')
      throw new Error(
        `The view kit's blocks require each other: ${[...chain, name].join(' -> ')}.`,
      );
    state.set(name, 'active');
    for (const dependency of block.requires) visit(dependency, [...chain, name]);
    state.set(name, 'done');
    order.push({ name, block });
  };
  for (const name of names) visit(name, []);
  return [
    ...order.filter((item) => item.block.layer === 'base'),
    ...order.filter((item) => item.block.layer !== 'base'),
  ];
}
